// ── Whitelist + route detect ─────────────────────────────────────
const allowedChatId = $env['TELEGRAM_ALLOWED_CHAT_ID'];
const msg = $input.first().json.message;
if (!msg) throw new Error('No message in update');

const chatId = String(msg.chat.id);
if (chatId !== String(allowedChatId)) {
  return [{ json: { skip: true, reason: 'not_allowed', chatId } }];
}

let promptText = '';
let hasPhoto = false;
let hasVoice = false;
let fileId = null;
let mimeType = 'image/jpeg';

if (msg.text) {
  promptText = msg.text;
} else if (msg.photo) {
  hasPhoto = true;
  const photos = msg.photo;
  fileId = photos[photos.length - 1].file_id;
  promptText = msg.caption || '(прикреплено фото)';
} else if (msg.voice) {
  hasVoice = true;
  fileId = msg.voice.file_id;
  mimeType = msg.voice.mime_type || 'audio/ogg';
  promptText = '';
} else {
  promptText = msg.caption || '[неизвестный тип сообщения]';
}

// Route by leading name (first line or "name:")
const ROUTES = [
  { id: 'zavod-osnovnoy', re: /^(завод\s*основной|завод|zavod(?:\s*osnovnoy)?|main\s*factory|factory)\s*[:\-–]?\s*/i },
  { id: 'finuchet-kolya', re: /^(финуч[её]т(?:\s*коля)?|finuchet(?:\s*kolya)?)\s*[:\-–]?\s*/i },
  { id: 'languages-on-site', re: /^(languages(?:\s*on\s*site)?|languages\-on\-site|eos|english(?:\s*on\s*site)?|englishonsite)\s*[:\-–]?\s*/i },
];

let routeId = ($env['DEFAULT_ROUTE'] || 'languages-on-site').toLowerCase();
let cleaned = promptText || '';
const firstLine = cleaned.split(/\n/)[0] || '';
for (const r of ROUTES) {
  const m = firstLine.match(r.re) || cleaned.match(r.re);
  if (m) {
    routeId = r.id;
    cleaned = cleaned.replace(r.re, '').trim() || cleaned;
    break;
  }
}

return [{
  json: {
    skip: false,
    source: 'telegram',
    chatId,
    messageId: msg.message_id,
    promptText: cleaned,
    rawPromptText: promptText,
    routeId,
    hasPhoto,
    hasVoice,
    fileId,
    mimeType,
    replyMode: 'telegram'
  }
}];

// Convert downloaded file binary to base64
const items = $input.all();
const item = items[0];
const binaryKey = Object.keys(item.binary || {})[0] || 'data';
const binaryData = item.binary[binaryKey];
const base64 = binaryData.data; // n8n stores base64 in .data
const mimeType = binaryData.mimeType || 'image/jpeg';

// Pull through the upstream context (chatId, promptText, etc.)
const upstream = item.json;

return [{
  json: {
    ...upstream,
    imageBase64: base64,
    imageMimeType: mimeType
  }
}];

// MVP: STT not implemented — reply immediately and stop
const item = $input.first().json;
return [{
  json: {
    ...item,
    voiceDeclined: true,
    declineMessage: '🎙 Голосовые сообщения пока не поддерживаются в этой версии. Напиши текстом или пришли скрин.'
  }
}];

// ── Route table → Create Agent payload ───────────────────────────
const item = $input.first().json;
const routeId = (item.routeId || $env['DEFAULT_ROUTE'] || 'languages-on-site').toLowerCase();

const TABLE = {
  'languages-on-site': {
    machine: $env['CURSOR_MACHINE_NAME_EOS'] || $env['CURSOR_MACHINE_NAME'] || 'Languages-on-site',
    repo: $env['CURSOR_REPO_URL_EOS'] || $env['CURSOR_REPO_URL'] || 'https://github.com/yad267/Languages-on-site.git',
    agentPrefix: 'TG Languages on site',
    context: 'Ты — агент Languages on site / EnglishOnSite. Правки только в проекте Languages-on-site / EnglishOnSite. Не трогай завод Спутник и финучёт. Формат: 1) Что сделано 2) Что осталось 3) Blockers.'
  },
  'zavod-osnovnoy': {
    machine: $env['CURSOR_MACHINE_NAME_ZAVOD'] || 'zavod-osnovnoy',
    repo: $env['CURSOR_REPO_URL_ZAVOD'] || 'https://github.com/yad267/see.git',
    agentPrefix: 'TG завод основной',
    context: 'Ты — завод основной на Маке Коли (постоянный worker zavod-osnovnoy). Доступны n8n, Google Sheets, контент-пайплайн. Выполни запрос (текст/скрин). Не ломай Languages on site и финучёт. Формат: 1) Что сделано 2) Что осталось 3) Blockers.'
  },
  'finuchet-kolya': {
    machine: $env['CURSOR_MACHINE_NAME_FINUCHET'] || 'finuchet-kolya',
    repo: $env['CURSOR_REPO_URL_FINUCHET'] || 'https://github.com/yad267/see.git',
    agentPrefix: 'TG финучёт Коля',
    context: 'Ты — финучёт Коля на this Mac. Данные: ~/Developer/finuchet-kolya/data/reminders.json. Добавляй/отмечай выполнено/список незакрытых. Не трогай Languages on site и завод. Формат: 1) Что сделано 2) Незакрытые 3) Blockers.'
  }
};

const route = TABLE[routeId] || TABLE['languages-on-site'];
const userText = item.promptText || '(нет текста)';
const fullPrompt = `${route.context}\n\n---\nИсточник: ${item.source || 'telegram'}\nМаршрут: ${routeId}\nЗапрос:\n${userText}`;

const payload = {
  chatId: item.chatId,
  replyMode: item.replyMode || 'telegram',
  callbackUrl: item.callbackUrl || null,
  routeId,
  machineName: route.machine,
  repoUrl: route.repo,
  agentName: `${route.agentPrefix}`,
  promptText: fullPrompt,
  images: []
};

if (item.imageBase64) {
  payload.images = [{ data: item.imageBase64, mimeType: item.imageMimeType || 'image/jpeg' }];
}

return [{ json: payload }];

const resp = $input.first().json;
const agentId = resp.id;
const runId = resp.latestRunId || (resp.runs && resp.runs[0] && resp.runs[0].id);
if (!agentId) throw new Error('No agentId in Create Agent response: ' + JSON.stringify(resp));
const built = $('Build Agent payload').first().json;
return [{ json: {
  agentId, runId,
  chatId: built.chatId,
  replyMode: built.replyMode || 'telegram',
  callbackUrl: built.callbackUrl || null,
  routeId: built.routeId,
  pollCount: 0,
  maxPolls: 40
}}];

const pollResp = $input.first().json;
const loopState = $('Wait 25s').first().json;
const status = pollResp.status || pollResp.state || 'UNKNOWN';
const terminalStatuses = ['FINISHED', 'ERROR', 'CANCELLED', 'EXPIRED', 'FAILED'];
const newPollCount = (loopState.pollCount || 0) + 1;
const maxPolls = loopState.maxPolls || 40;
const timedOut = newPollCount >= maxPolls;
return [{ json: {
  agentId: loopState.agentId,
  runId: loopState.runId,
  chatId: loopState.chatId,
  replyMode: loopState.replyMode,
  callbackUrl: loopState.callbackUrl,
  routeId: loopState.routeId,
  pollCount: newPollCount,
  maxPolls,
  status,
  result: pollResp.result || pollResp.output || null,
  isTerminal: terminalStatuses.includes(String(status).toUpperCase()) || timedOut,
  timedOut,
  rawResponse: pollResp
}}];

// Loop back: carry state to Wait node
const item = $input.first().json;
return [{ json: item }];

const item = $input.first().json;
const MAX_LEN = 3500;
let text = '';
if (item.timedOut) {
  text = `⏰ Timeout (${item.routeId}): статус ${item.status}\nagentId=${item.agentId}`;
} else if (['ERROR', 'CANCELLED', 'EXPIRED', 'FAILED'].includes(String(item.status || '').toUpperCase())) {
  text = `❌ *${item.routeId}* статус *${item.status}*\n`;
  if (item.result) text += String(item.result).slice(0, MAX_LEN - text.length);
} else {
  const result = item.result ? String(item.result) : '(нет текста в result)';
  text = `✅ *${item.routeId}* готово\n\n${result}`.slice(0, MAX_LEN);
}
return [{ json: { chatId: item.chatId, text, replyMode: item.replyMode, callbackUrl: item.callbackUrl, routeId: item.routeId } }];

// Ingress from any cloud Cursor chat / device
const body = $input.first().json.body || $input.first().json;
const secret = $env['CLOUD_ROUTER_SECRET'];
if (secret) {
  const got = body.secret || $input.first().json.headers?.['x-router-secret'];
  if (String(got || '') !== String(secret)) {
    return [{ json: { skip: true, reason: 'bad_secret', chatId: String(body.reply_chat_id || body.chatId || '') } }];
  }
}

const allowed = String($env['TELEGRAM_ALLOWED_CHAT_ID'] || '');
const chatId = String(body.reply_chat_id || body.chatId || allowed);
if (allowed && chatId && chatId !== allowed && body.force_chat_id !== true) {
  // still allow if explicit reply_chat_id equals allowed; otherwise require match
}

let routeId = String(body.target || body.route || body.routeId || '').toLowerCase().trim();
const aliasMap = {
  'завод основной': 'zavod-osnovnoy', 'завод': 'zavod-osnovnoy', 'zavod': 'zavod-osnovnoy', 'factory': 'zavod-osnovnoy',
  'финучёт коля': 'finuchet-kolya', 'финучет коля': 'finuchet-kolya', 'финучёт': 'finuchet-kolya', 'финучет': 'finuchet-kolya', 'finuchet': 'finuchet-kolya',
  'languages on site': 'languages-on-site', 'languages-on-site': 'languages-on-site', 'eos': 'languages-on-site'
};
if (aliasMap[routeId]) routeId = aliasMap[routeId];
if (!['languages-on-site','zavod-osnovnoy','finuchet-kolya'].includes(routeId)) {
  routeId = ($env['DEFAULT_ROUTE'] || 'languages-on-site');
}

const promptText = body.text || body.prompt || body.message || '';
const images = [];
if (body.image_base64) {
  images.push({ data: body.image_base64, mimeType: body.image_mime || 'image/jpeg' });
}
if (Array.isArray(body.images)) {
  for (const im of body.images) {
    if (im && im.data) images.push({ data: im.data, mimeType: im.mimeType || im.mime || 'image/jpeg' });
  }
}

const out = {
  skip: false,
  source: 'cloud',
  chatId: chatId || allowed,
  messageId: null,
  promptText,
  rawPromptText: promptText,
  routeId,
  hasPhoto: false, // image already in imageBase64 — skip Telegram getFile branch
  hasVoice: false,
  fileId: null,
  mimeType: 'image/jpeg',
  replyMode: body.reply_mode || 'telegram',
  callbackUrl: body.callback_url || null
};
if (images[0]) {
  out.imageBase64 = images[0].data;
  out.imageMimeType = images[0].mimeType;
}
return [{ json: out }];
